import java.util.*;
import java.io.*;

public class CF552C {
  public static int maxPowerIndex, baseNumber;
  public static HashSet<Long> sumSet;
  public static void main(String[] args) throws Exception {
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    PrintWriter writer = new PrintWriter(System.out);

    String[] parts = reader.readLine().split(" ");
    int baseInput = Integer.parseInt(parts[0]);
    long targetInput = Long.parseLong(parts[1]);

    int maxExp = 0;
    for (int i = 0; baseInput > 2 && i < 21; i++) {
      maxExp = i;
      if (Math.pow(baseInput, i) > 1e9) break;
    }

    sumSet = new HashSet<>();
    if (baseInput > 2) buildSums(0, 0, maxExp);

    boolean isPossible = false;
    if (baseInput == 2) isPossible = true;

    for (Long val : sumSet) {
      if (val >= targetInput && sumSet.contains(val - targetInput)) {
        isPossible = true;
        break;
      }
    }

    writer.println(isPossible ? "YES" : "NO");
    writer.close();
  }

  static void buildSums(int index, long sum, int maxExp) {
    if (index > maxExp) {
      sumSet.add(sum);
      return;
    }
    buildSums(index + 1, sum + (long) Math.pow(baseNumber, index), maxExp);
    buildSums(index + 1, sum, maxExp);
  }
}
