#include <bits/stdc++.h>
using namespace std;

int maxPowerIndex, baseNumber;
unordered_set<long long> sumSet;

void buildSums(int index, long long sum, int maxExp) {
    if (index > maxExp) {
        sumSet.insert(sum);
        return;
    }
    buildSums(index + 1, sum + (long long)pow(baseNumber, index), maxExp);
    buildSums(index + 1, sum, maxExp);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int baseInput;
    long long targetInput;
    cin >> baseInput >> targetInput;

    int maxExp = 0;
    for (int i = 0; baseInput > 2 && i < 21; i++) {
        maxExp = i;
        if (pow(baseInput, i) > 1e9) break;
    }

    if (baseInput > 2) {
        buildSums(0, 0, maxExp);
    }

    bool isPossible = false;
    if (baseInput == 2) {
        isPossible = true;
    }

    for (auto val : sumSet) {
        if (val >= targetInput && sumSet.count(val - targetInput)) {
            isPossible = true;
            break;
        }
    }

    cout << (isPossible ? "YES" : "NO") << "\n";

    return 0;
}
